import base64,hashlib,json,os,stat
from pathlib import Path
INPUTS = json.loads('[{"name":"export_h2_retained_images.py","bytes":25293,"sha256":"37538f62fd81398262ccde1b9cfa0d1cb0163b115e108b80220ab7af8f929365","base64":""},{"name":"H2-export-plan.json","bytes":169237,"sha256":"2a18729275fe2051b3f691fce56542e2d1291193e983330fe82601caf22349b3","base64":""}]')
STAGE = Path("/home/qian-qi/work/hepta-h2-actual-elf-export-inputs-20261105-93bfc-01")
if STAGE.parent.resolve(strict=True) != STAGE.parent:
    raise ValueError("canonical existing input parent required")
STAGE.mkdir(mode=0o700)
for item in INPUTS:
    raw=base64.b64decode(item["base64"],validate=True)
    if len(raw)!=item["bytes"] or hashlib.sha256(raw).hexdigest()!=item["sha256"]:
        raise ValueError("frozen input byte/hash mismatch")
    path=STAGE/item["name"]
    with path.open("xb") as output:
        if output.write(raw)!=len(raw): raise ValueError("short frozen-input write")
        output.flush(); os.fsync(output.fileno())
    descriptor=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK)
    with os.fdopen(descriptor,"rb") as actual:
        info=os.fstat(actual.fileno())
        if not stat.S_ISREG(info.st_mode) or info.st_nlink!=1 or info.st_size!=item["bytes"]:
            raise ValueError("regular exact frozen input required")
        readback=actual.read(item["bytes"]+1)
    if len(readback)!=item["bytes"] or hashlib.sha256(readback).hexdigest()!=item["sha256"]:
        raise ValueError("actual written input hash mismatch")
for directory in (STAGE,STAGE.parent):
    descriptor=os.open(directory,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
    try: os.fsync(descriptor)
    finally: os.close(descriptor)
os.execv("/usr/bin/python3",["/usr/bin/python3","-B",str(STAGE/"export_h2_retained_images.py"),"--plan",str(STAGE/"H2-export-plan.json"),"--expected-plan-sha256","2a18729275fe2051b3f691fce56542e2d1291193e983330fe82601caf22349b3","--expected-exporter-sha256","37538f62fd81398262ccde1b9cfa0d1cb0163b115e108b80220ab7af8f929365"])
